# -*- coding: utf-8 -*-
"""Quantum Victory Streamlit Cloud launcher — 1.6.0.
The application payload is embedded so the GitHub mobile upload only needs
this file plus requirements.txt. No legacy Nafezu wrapper is used as entrypoint.
Payload SHA-256: 3e451a2271b9ce32599fdfeacc827acc7369dc71e8071adc916d700a000dbd53
"""
from __future__ import annotations
import base64, os, runpy, sys, zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
RUNTIME = ROOT / ".qv_runtime_1_6_0"
PAYLOAD_SHA256 = "3e451a2271b9ce32599fdfeacc827acc7369dc71e8071adc916d700a000dbd53"
PAYLOAD = ""

def _ensure_runtime():
    import hashlib
    raw = base64.b64decode(PAYLOAD.encode("ascii"))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise RuntimeError("QV embedded payload fingerprint mismatch")
    marker = RUNTIME / ".payload_sha256"
    if not marker.exists() or marker.read_text(encoding="utf-8") != PAYLOAD_SHA256:
        if RUNTIME.exists():
            import shutil
            shutil.rmtree(RUNTIME)
        RUNTIME.mkdir(parents=True, exist_ok=True)
        import io
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            z.extractall(RUNTIME)
        marker.write_text(PAYLOAD_SHA256, encoding="utf-8")
    sys.path.insert(0, str(RUNTIME))

_ensure_runtime()

# Secure Streamlit Secrets -> environment bridge for durable persistence.
# Secrets are never written to the repository or displayed by the app.
try:
    import streamlit as _st
    _secret_map = {
        "QV_GITHUB_TOKEN": "QV_GITHUB_TOKEN",
        "QV_GITHUB_REPOSITORY": "QV_GITHUB_REPOSITORY",
        "QV_GITHUB_BRANCH": "QV_GITHUB_BRANCH",
        "QV_GITHUB_ARCHIVE_PREFIX": "QV_GITHUB_ARCHIVE_PREFIX",
        "QV_GITHUB_API": "QV_GITHUB_API",
        "QV_DURABLE_BACKEND": "QV_DURABLE_BACKEND",
    }
    for _secret_key, _env_key in _secret_map.items():
        try:
            if _secret_key in _st.secrets and str(_st.secrets[_secret_key]).strip():
                os.environ[_env_key] = str(_st.secrets[_secret_key]).strip()
        except Exception:
            pass
except Exception:
    pass

# If the durable GitHub credentials are configured, make the backend active
# automatically; otherwise remain LOCAL_RUNTIME_ONLY and fail closed.
if os.getenv("QV_GITHUB_TOKEN", "").strip() and os.getenv("QV_GITHUB_REPOSITORY", "").strip():
    os.environ["QV_DURABLE_BACKEND"] = "GITHUB_CONTENTS"

os.environ.setdefault("QV_OFFLINE_MODE", "1")
runpy.run_path(str(RUNTIME / "streamlit_app.py"), run_name="__main__")
